-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.availability_overrides (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    date date NOT NULL,
    is_unavailable boolean DEFAULT true NOT NULL,
    start_minute integer,
    end_minute integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone
);


--
-- Name: availability_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.availability_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    day_of_week smallint NOT NULL,
    start_minute integer NOT NULL,
    end_minute integer NOT NULL,
    timezone text DEFAULT 'UTC'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone,
    CONSTRAINT availability_rules_day_of_week_check CHECK (((day_of_week >= 0) AND (day_of_week <= 6))),
    CONSTRAINT availability_rules_end_minute_check CHECK (((end_minute >= 0) AND (end_minute <= 1439))),
    CONSTRAINT availability_rules_start_minute_check CHECK (((start_minute >= 0) AND (start_minute <= 1439)))
);


